@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Noto+Serif+JP:wght@300;400;600;700&family=Zen+Kaku+Gothic+New:wght@300;400;500;700&display=swap');

/* ==========================================================================
   CSS Variables & Design Tokens
   ========================================================================== */
:root {
  --color-primary: #2C4A3E;        /* 深いフォレストグリーン */
  --color-primary-light: #446958;  /* 明るめのフォレストグリーン */
  --color-primary-dark: #1A3128;   /* 濃緑 */
  --color-accent: #A67C52;         /* コーヒーローストブラウン */
  --color-accent-light: #C49E73;   /* キャメル */
  --color-accent-gold: #D4AF37;    /* アンティークゴールド */
  --color-bg-main: #FBF8F5;        /* 柔らかなミルクエクリュ */
  --color-bg-card: #FFFFFF;        /* ピュアホワイト */
  --color-bg-warm: #F4EFEA;        /* 温かみのあるサンドベージュ */
  --color-text-main: #2A2421;      /* 深いエスプレッソブラック */
  --color-text-muted: #6B625B;     /* モカグレー */
  --color-text-light: #9B9189;     /* ソフトアッシュ */
  --color-border: #E8E0D7;         /* 微細な枠線カラー */
  --color-border-dark: #D4C9BC;    /* 濃い枠線カラー */

  --font-serif: 'Noto Serif JP', 'Cormorant Garamond', serif;
  --font-sans: 'Zen Kaku Gothic New', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-en: 'Cormorant Garamond', serif;

  --shadow-sm: 0 2px 8px rgba(44, 36, 33, 0.04);
  --shadow-md: 0 6px 20px rgba(44, 36, 33, 0.08);
  --shadow-lg: 0 14px 34px rgba(44, 36, 33, 0.12);
  --shadow-hover: 0 20px 40px rgba(44, 36, 33, 0.16);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --transition-fast: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-normal: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

/* ==========================================================================
   Base & Reset
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg-main);
  color: var(--color-text-main);
  line-height: 1.8;
  letter-spacing: 0.03em;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  outline: none;
  transition: var(--transition-fast);
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition-fast);
}

/* ==========================================================================
   Layout & Structure
   ========================================================================== */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--color-bg-main);
  background-image: 
    radial-gradient(#E9E1D6 0.75px, transparent 0.75px),
    radial-gradient(#E9E1D6 0.75px, var(--color-bg-main) 0.75px);
  background-size: 30px 30px;
  background-position: 0 0, 15px 15px;
}

.section-container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 100px 24px;
}

@media (max-width: 768px) {
  .section-container {
    padding: 64px 20px;
  }
}

.section-header {
  text-align: center;
  margin-bottom: 56px;
  position: relative;
}

.section-title {
  font-family: var(--font-serif);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  letter-spacing: 0.06em;
  line-height: 1.4;
  margin-bottom: 12px;
}

@media (max-width: 768px) {
  .section-title {
    font-size: 1.85rem;
  }
}

.section-subtitle {
  font-family: var(--font-en);
  font-size: 1.15rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
  display: block;
  font-weight: 600;
}

.section-subtitle::before,
.section-subtitle::after {
  content: "—";
  margin: 0 10px;
  opacity: 0.6;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: rgba(251, 248, 245, 0.94);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(232, 224, 215, 0.8);
  transition: var(--transition-normal);
}

.header-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 16px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  flex-direction: column;
  text-decoration: none;
}

.logo-title {
  font-family: var(--font-en);
  font-size: 1.65rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--color-primary-dark);
  line-height: 1;
}

.logo-sub {
  font-size: 0.68rem;
  letter-spacing: 0.25em;
  color: var(--color-accent);
  text-transform: uppercase;
  margin-top: 4px;
  font-weight: 500;
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-link {
  font-family: var(--font-serif);
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--color-text-main);
  position: relative;
  padding: 4px 0;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1.5px;
  background-color: var(--color-accent);
  transition: width var(--transition-fast);
}

.nav-link:hover {
  color: var(--color-accent);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-btn {
  padding: 8px 20px;
  background-color: var(--color-primary);
  color: #FFFFFF;
  border-radius: var(--radius-full);
  font-size: 0.88rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  box-shadow: 0 4px 12px rgba(44, 74, 62, 0.2);
  transition: var(--transition-fast);
}

.nav-btn:hover {
  background-color: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(44, 74, 62, 0.3);
}

@media (max-width: 840px) {
  .header-container {
    padding: 14px 20px;
  }
  .nav-menu {
    gap: 16px;
  }
  .nav-link {
    font-size: 0.85rem;
  }
}

@media (max-width: 680px) {
  .nav-menu {
    display: none;
  }
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 120px 24px 80px;
  background: 
    linear-gradient(rgba(26, 49, 40, 0.45), rgba(44, 36, 33, 0.55)),
    url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=2000&q=80') center/cover no-repeat;
  color: #FFFFFF;
  text-align: center;
}

.hero::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 90px;
  background: linear-gradient(to top, var(--color-bg-main), transparent);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 820px;
  margin: 0 auto;
  animation: heroFadeIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes heroFadeIn {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-badge {
  display: inline-block;
  padding: 6px 20px;
  margin-bottom: 24px;
  background-color: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: var(--radius-full);
  backdrop-filter: blur(8px);
  font-family: var(--font-en);
  font-size: 0.95rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #FFF6EC;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: 3.4rem;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.08em;
  margin-bottom: 24px;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.35);
}

@media (max-width: 768px) {
  .hero-title {
    font-size: 2.2rem;
  }
}

.hero-subtitle {
  font-size: 1.12rem;
  line-height: 1.9;
  font-weight: 400;
  color: #F7F3EE;
  margin-bottom: 40px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 768px) {
  .hero-subtitle {
    font-size: 0.98rem;
  }
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

.btn-primary,
.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 34px;
  border-radius: var(--radius-full);
  font-size: 0.96rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  transition: all var(--transition-normal);
  text-decoration: none;
}

.btn-primary {
  background-color: var(--color-accent);
  color: #FFFFFF;
  box-shadow: 0 8px 24px rgba(166, 124, 82, 0.35);
}

.btn-primary:hover {
  background-color: #8E653E;
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(166, 124, 82, 0.45);
}

.btn-outline {
  background-color: transparent;
  color: #FFFFFF;
  border: 1.5px solid rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(4px);
}

.btn-outline:hover {
  background-color: #FFFFFF;
  color: var(--color-primary-dark);
  border-color: #FFFFFF;
  transform: translateY(-2px);
}

/* ==========================================================================
   Concept Section
   ========================================================================== */
.concept-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

@media (max-width: 900px) {
  .concept-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

.concept-card {
  background: var(--color-bg-card);
  padding: 44px 32px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  text-align: center;
  transition: var(--transition-normal);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent-light);
}

.concept-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--color-bg-warm);
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  box-shadow: inset 0 0 0 1px rgba(166, 124, 82, 0.2);
  transition: var(--transition-fast);
}

.concept-card:hover .concept-icon {
  background-color: var(--color-primary);
  color: #FFFFFF;
}

.concept-card-title {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 16px;
  line-height: 1.4;
}

.concept-card-text {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.85;
}

/* ==========================================================================
   Menu Section
   ========================================================================== */
.menu-section {
  background-color: #F6F1EA;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.category-tabs {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 44px;
  flex-wrap: wrap;
}

.tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--color-text-muted);
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  color: var(--color-primary);
  border-color: var(--color-primary-light);
  background-color: #FFFFFF;
}

.category-tabs .tab-btn.tab-btn-active,
.tab-btn.tab-btn-active {
  background-color: var(--color-primary);
  color: #FFFFFF;
  border-color: var(--color-primary);
  box-shadow: 0 4px 14px rgba(44, 74, 62, 0.25);
}

.category-tabs .tab-btn.tab-btn-active:hover,
.tab-btn.tab-btn-active:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-light);
  color: #FFFFFF;
}

.tab-count {
  font-size: 0.8rem;
  opacity: 0.85;
  font-family: var(--font-en);
}

.menu-empty-state {
  text-align: center;
  padding: 60px 20px;
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px dashed var(--color-border-dark);
}

.menu-empty-text {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

@media (max-width: 1024px) {
  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .menu-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

.menu-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  transition: var(--transition-normal);
  display: flex;
  flex-direction: column;
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent-light);
}

.menu-image-wrapper {
  position: relative;
  width: 100%;
  height: 220px;
  overflow: hidden;
  background-color: var(--color-bg-warm);
}

.menu-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.menu-card:hover .menu-img {
  transform: scale(1.06);
}

.menu-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: linear-gradient(135deg, var(--color-accent), #8E653E);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  letter-spacing: 0.05em;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18);
  z-index: 2;
}

.menu-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.menu-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  border-bottom: 1px dashed var(--color-border);
  padding-bottom: 10px;
}

.menu-name {
  font-family: var(--font-serif);
  font-size: 1.18rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.35;
}

.menu-price {
  font-family: var(--font-en);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  white-space: nowrap;
}

.menu-desc {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin-bottom: 18px;
  flex-grow: 1;
}

.menu-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.menu-tag {
  font-size: 0.75rem;
  color: var(--color-primary-light);
  background-color: var(--color-bg-warm);
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}

/* ==========================================================================
   Gallery Section
   ========================================================================== */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

@media (max-width: 992px) {
  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .gallery-grid {
    grid-template-columns: 1fr;
  }
}

.gallery-item {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 4 / 3;
  box-shadow: var(--shadow-sm);
  background-color: var(--color-bg-warm);
}

.gallery-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.gallery-caption {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(26, 49, 40, 0.88) 0%, rgba(26, 49, 40, 0.2) 60%, transparent 100%);
  display: flex;
  align-items: flex-end;
  padding: 20px;
  color: #FFFFFF;
  font-family: var(--font-serif);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  opacity: 0;
  transform: translateY(8px);
  transition: all var(--transition-normal);
}

.gallery-item:hover .gallery-img {
  transform: scale(1.08);
}

.gallery-item:hover .gallery-caption {
  opacity: 1;
  transform: translateY(0);
}

/* ==========================================================================
   Access & Store Info Section
   ========================================================================== */
.access-section {
  background-color: var(--color-bg-main);
}

.access-container {
  width: 100%;
}

.access-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 40px;
  align-items: stretch;
}

@media (max-width: 900px) {
  .access-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

.access-info-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  padding: 36px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.info-row {
  display: flex;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--color-border);
}

.info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.info-label {
  width: 110px;
  flex-shrink: 0;
  font-family: var(--font-serif);
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--color-primary-dark);
}

.info-value {
  flex-grow: 1;
  font-size: 0.94rem;
  color: var(--color-text-main);
  line-height: 1.6;
}

.phone-link {
  color: var(--color-primary-dark);
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: color var(--transition-fast);
}

.phone-link:hover {
  color: var(--color-accent);
}

.facility-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.facility-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background-color: var(--color-bg-warm);
  border: 1px solid var(--color-border-dark);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--color-text-main);
}

.facility-icon {
  font-size: 0.9rem;
}

.map-visual-box {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.map-placeholder {
  position: relative;
  width: 100%;
  height: 230px;
  background: 
    radial-gradient(#C49E73 1px, transparent 1px),
    linear-gradient(135deg, #e4ded7 0%, #d8d0c6 100%);
  background-size: 24px 24px, 100% 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-dark);
}

.map-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-primary);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  box-shadow: 0 4px 12px rgba(44, 74, 62, 0.35);
  animation: pulsePin 2s infinite ease-in-out;
}

@keyframes pulsePin {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

.map-guide-list {
  padding: 24px 28px 16px;
  list-style: none;
  background-color: #FFFFFF;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-grow: 1;
}

.map-guide-item {
  position: relative;
  padding-left: 28px;
  font-size: 0.9rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.map-guide-item::before {
  content: "✔";
  position: absolute;
  left: 0;
  top: 0;
  color: var(--color-accent);
  font-weight: 700;
