import { useState } from 'react';
import { CafeMenuItem, MenuCategoryFilter } from '../types';

interface MenuSectionProps {
  items?: CafeMenuItem[];
}

interface CategoryTabItem {
  id: MenuCategoryFilter;
  label: string;
}

const CATEGORY_TABS: CategoryTabItem[] = [
  { id: 'all', label: 'すべて' },
  { id: 'coffee', label: 'コーヒー' },
  { id: 'drink', label: 'その他ドリンク' },
  { id: 'food', label: 'フード' },
  { id: 'dessert', label: 'デザート' }
];

const MenuSection = ({ items = [] }: MenuSectionProps) => {
  const [activeTab, setActiveTab] = useState<MenuCategoryFilter>('all');

  const filteredItems = activeTab === 'all'
    ? items
    : items.filter((item) => item.category === activeTab);

  const getCategoryCount = (category: MenuCategoryFilter) => {
    if (category === 'all') {
      return items.length;
    }
    return items.filter((item) => item.category === category).length;
  };

  return (
    <section id="menu" className="menu-section">
      <div className="section-container">
        <header className="section-header">
          <span className="section-subtitle">Our Menu</span>
          <h2 className="section-title">こだわりのメニュー</h2>
        </header>

        {/* カテゴリ切り替えタブ */}
        <div className="category-tabs" role="tablist" aria-label="メニューカテゴリー切り替え">
          {CATEGORY_TABS.map((tab) => {
            const isActive = activeTab === tab.id;
            const count = getCategoryCount(tab.id);
            return (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={isActive}
                className={`tab-btn ${isActive ? 'tab-btn-active' : ''}`}
                onClick={() => setActiveTab(tab.id)}
              >
                <span>{tab.label}</span>
                <span className="tab-count">({count})</span>
              </button>
            );
          })}
        </div>

        {/* メニューカード一覧 / Empty State */}
        {filteredItems.length === 0 ? (
          <div className="menu-empty-state">
            <p className="menu-empty-text">現在、該当するメニューはございません。</p>
          </div>
        ) : (
          <div className="menu-grid">
            {filteredItems.map((item) => (
              <article key={item.id} className="menu-card">
                <div className="menu-image-wrapper">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="menu-img"
                    loading="lazy"
                  />
                  {item.isRecommended && (
                    <span className="menu-badge">おすすめ</span>
                  )}
                </div>

                <div className="menu-body">
                  <div className="menu-header">
                    <h3 className="menu-name">{item.name}</h3>
                    <span className="menu-price">¥{item.price.toLocaleString()}</span>
                  </div>

                  <p className="menu-desc">{item.description}</p>

                  {item.tags && item.tags.length > 0 && (
                    <div className="menu-tags" aria-label="特徴タグ">
                      {item.tags.map((tag) => (
                        <span key={tag} className="menu-tag">
                          #{tag}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </section>
  );
};

export default MenuSection;

