const getFacilityIcon = (facility: string): string => {
  if (facility.includes('Wi-Fi')) return '📶';
  if (facility.includes('電源') || facility.includes('USB')) return '🔌';
  if (facility.includes('ペット')) return '🐾';
  if (facility.includes('禁煙')) return '🚭';
  if (facility.includes('キャッシュレス')) return '💳';
  if (facility.includes('テイクアウト')) return '☕';
  if (facility.includes('スロープ') || facility.includes('車椅子')) return '♿';
  return '✔';
};

